import type { z } from "zod";
import type {
	courseSchema,
	courseFiltersSchema,
	lessonSchema,
	quizSchema,
} from "./schemas";
/** CMS-backed course with serialized timestamps and curriculum count. */
export type Course = z.output<typeof courseSchema> & {
	id: string;
	createdAt: string;
	updatedAt: string;
	lessonCount: number;
};
export type CourseFilters = z.input<typeof courseFiltersSchema>;
export type Quiz = z.output<typeof quizSchema>;
/** Student-safe quiz question; answer keys are removed from lesson responses. */
export type PublicQuiz = Omit<Quiz, "questions"> & {
	questions: Omit<Quiz["questions"][number], "correctAnswer">[];
};
export type Section = {
	id: string;
	courseId: string;
	title: string;
	order: number;
};
export type Lesson = Omit<z.output<typeof lessonSchema>, "quiz"> & {
	id: string;
	courseId: string;
	quiz?: Quiz | PublicQuiz | null;
};
export type LessonSummary = Pick<
	Lesson,
	| "id"
	| "courseId"
	| "title"
	| "sectionId"
	| "type"
	| "durationMins"
	| "order"
	| "isFreePreview"
>;
export type Enrollment = {
	id: string;
	courseId: string;
	userId: string;
	status: "enrolled" | "completed" | "cancelled";
	progressPct: number;
	lastLessonId?: string | null;
	certificateId?: string | null;
	paymentRef?: string | null;
	enrolledAt: string;
	completedAt?: string | null;
};
export type LessonProgress = {
	id: string;
	enrollmentId: string;
	lessonId: string;
	completed: boolean;
	completedAt?: string | null;
	positionSecs: number;
};
export type QuizAttempt = {
	id: string;
	lessonId: string;
	userId: string;
	answers: { questionId: string; answer: number }[];
	score: number;
	passed: boolean;
	attemptedAt: string;
};
export type Review = {
	id: string;
	courseId: string;
	userId: string;
	rating: number;
	body: string;
	createdAt: string;
};
export type CourseDetail = Course & {
	sections: Section[];
	lessons: LessonSummary[];
	reviews: Review[];
	enrollment: null;
};
/** Enrollment, payment, assessment, and completion lifecycle callbacks. */
export interface SchoolPluginHooks {
	/** Runs before enrollment. Returning false rejects the request. */
	onBeforeEnroll?: (
		userId: string,
		course: Course,
	) => Promise<boolean> | boolean;
	/** Runs after the enrollment has been persisted. */
	onAfterEnroll?: (
		enrollment: Enrollment,
		course: Course,
	) => Promise<void> | void;
	/** Generate a certificate after completion; the returned unique ID is stored on the enrollment. */
	onCourseComplete?: (
		enrollment: Enrollment,
		course: Course,
	) => Promise<{ certificateId: string }> | { certificateId: string };
	/** Runs after a scored quiz attempt is persisted. */
	onQuizSubmit?: (attempt: QuizAttempt, lesson: Lesson) => Promise<void> | void;
}
/** School backend configuration. */
export interface SchoolBackendOptions {
	/** Enrollment and completion lifecycle callbacks. */
	hooks?: SchoolPluginHooks;
	/** Default quiz pass percentage, used when a quiz has no override. @default 70 */
	quizPassMark?: number;
	/** Enable certificate generation and public verification. @default true */
	certificatesEnabled?: boolean;
	/** Verify or collect payment on the server. Required for paid courses; falsy results reject enrollment. */
	paymentAdapter?: {
		createPayment: (input: {
			userId: string;
			course: Course;
			idempotencyKey: string;
		}) => Promise<{ paymentRef: string } | null>;
	};
}
/** Validated authoring input shapes used by instructor forms. */
export type CourseInput = z.input<typeof courseSchema>;
export type LessonInput = z.input<typeof lessonSchema>;
export type CatalogFilters = CourseFilters;
export type StudentCoursesResult = {
	items: (Enrollment & {
		course: Course;
		lessons: LessonSummary[];
		/** A configured certificate provider has not yet issued this completed course's certificate. */
		certificatePending: boolean;
	})[];
};
export type LessonResult = {
	lesson: Lesson;
	enrollment: Enrollment | null;
	progress: LessonProgress | null;
	attempts: QuizAttempt[];
};
export type CourseStudentsResult = {
	items: Enrollment[];
	analytics: {
		totalEnrolled: number;
		totalCompleted: number;
		completionRate: number;
		enrollmentsOverTime: { date: string; count: number }[];
	};
};
export type CertificateResult = {
	certificateId: string;
	courseTitle: string;
	completedAt?: string | null;
};

import { z } from "zod";
import type { ContentTypeConfig } from "@btst/stack/plugins/cms/api";

const safeUrl = z
	.string()
	.url()
	.refine((value) => /^https?:\/\//i.test(value), "Use an HTTP or HTTPS URL");
const optionalUrl = z.union([safeUrl, z.literal("")]).optional();
/** Course content stored by the CMS plugin. Prices are integer minor currency units. */
export const courseSchema = z.object({
	title: z.string().trim().min(1).max(200),
	slug: z
		.string()
		.regex(
			/^(?!(?:me|instructor)$)[a-z0-9]+(?:-[a-z0-9]+)*$/,
			"Use a lowercase course address; me and instructor are reserved",
		)
		.max(200),
	description: z.string().max(100000).default(""),
	coverImage: optionalUrl,
	instructorId: z.string().min(1).max(200),
	instructorName: z.string().max(200).default(""),
	instructorBio: z.string().max(10000).default(""),
	category: z.string().max(100).default(""),
	tags: z.array(z.string().max(100)).max(30).default([]),
	difficulty: z
		.enum(["beginner", "intermediate", "advanced"])
		.default("beginner"),
	durationMins: z.number().int().nonnegative().default(0),
	price: z.number().int().nonnegative().default(0),
	currency: z
		.string()
		.regex(/^[A-Z]{3}$/)
		.default("USD"),
	status: z.enum(["draft", "published", "archived"]).default("draft"),
	featured: z.boolean().default(false),
});
/** Partial edits preserve omitted values instead of applying creation defaults. */
export const courseUpdateSchema = courseSchema.partial().extend({
	description: courseSchema.shape.description.removeDefault().optional(),
	instructorName: courseSchema.shape.instructorName.removeDefault().optional(),
	instructorBio: courseSchema.shape.instructorBio.removeDefault().optional(),
	category: courseSchema.shape.category.removeDefault().optional(),
	tags: courseSchema.shape.tags.removeDefault().optional(),
	difficulty: courseSchema.shape.difficulty.removeDefault().optional(),
	durationMins: courseSchema.shape.durationMins.removeDefault().optional(),
	price: courseSchema.shape.price.removeDefault().optional(),
	currency: courseSchema.shape.currency.removeDefault().optional(),
	status: courseSchema.shape.status.removeDefault().optional(),
	featured: courseSchema.shape.featured.removeDefault().optional(),
});
/** Register alongside the School backend in cmsBackendPlugin({ contentTypes }). */
export const SCHOOL_COURSE_CONTENT_TYPE: ContentTypeConfig = {
	name: "Course",
	slug: "school-course",
	schema: courseSchema,
};
/** Public course list filtering. Draft/publication controls are deliberately absent. */
export const courseFiltersSchema = z.object({
	category: z.string().max(100).optional(),
	difficulty: z.enum(["beginner", "intermediate", "advanced"]).optional(),
	maxDurationMins: z.coerce.number().int().nonnegative().optional(),
	pricing: z.enum(["free", "paid"]).optional(),
	featured: z
		.enum(["true", "false"])
		.transform((v) => v === "true")
		.or(z.boolean())
		.optional(),
	query: z.string().max(200).optional(),
});
/** Multiple choice quiz definition. Correct answer indexes are only returned to instructors. */
export const quizSchema = z
	.object({
		questions: z
			.array(
				z.object({
					id: z.string().min(1).max(100),
					question: z.string().min(1).max(2000),
					options: z.array(z.string().min(1).max(1000)).min(2).max(10),
					correctAnswer: z.number().int().nonnegative(),
				}),
			)
			.min(1)
			.max(100),
		passMark: z.number().min(0).max(100).optional(),
		maxAttempts: z.number().int().min(1).max(100).optional(),
	})
	.superRefine((quiz, ctx) => {
		const ids = new Set<string>();
		for (const [index, q] of quiz.questions.entries()) {
			if (q.correctAnswer >= q.options.length)
				ctx.addIssue({
					code: "custom",
					path: ["questions", index, "correctAnswer"],
					message: "Correct answer must match an option",
				});
			if (ids.has(q.id))
				ctx.addIssue({
					code: "custom",
					path: ["questions", index, "id"],
					message: "Question IDs must be unique",
				});
			ids.add(q.id);
		}
	});
/** Lesson content, resource links, and optional server-scored quiz. */
export const lessonSchema = z
	.object({
		title: z.string().trim().min(1).max(200),
		sectionId: z.string().min(1).nullable().optional(),
		type: z.enum(["video", "text", "quiz"]),
		content: z.string().max(100000).default(""),
		videoUrl: optionalUrl,
		durationMins: z.number().int().nonnegative().default(0),
		order: z.number().int().nonnegative().default(0),
		isFreePreview: z.boolean().default(false),
		resources: z
			.array(z.object({ label: z.string().min(1).max(200), url: safeUrl }))
			.max(30)
			.default([]),
		quiz: quizSchema.nullable().optional(),
	})
	.superRefine((lesson, ctx) => {
		if (lesson.type === "quiz" && !lesson.quiz)
			ctx.addIssue({
				code: "custom",
				path: ["quiz"],
				message: "Quiz lessons require questions",
			});
		if (lesson.type === "video" && !lesson.videoUrl)
			ctx.addIssue({
				code: "custom",
				path: ["videoUrl"],
				message: "Video lessons require a video URL",
			});
	});
/** Lesson patches preserve omitted metadata and are validated after merging stored content. */
export const lessonUpdateSchema = z.object({
	title: lessonSchema.shape.title.optional(),
	sectionId: lessonSchema.shape.sectionId,
	type: lessonSchema.shape.type.optional(),
	content: lessonSchema.shape.content.removeDefault().optional(),
	videoUrl: lessonSchema.shape.videoUrl,
	durationMins: lessonSchema.shape.durationMins.removeDefault().optional(),
	order: lessonSchema.shape.order.removeDefault().optional(),
	isFreePreview: lessonSchema.shape.isFreePreview.removeDefault().optional(),
	resources: lessonSchema.shape.resources.removeDefault().optional(),
	quiz: lessonSchema.shape.quiz,
});
export const sectionSchema = z.object({
	title: z.string().trim().min(1).max(200),
	order: z.number().int().nonnegative().default(0),
});
/** Partial section edits do not reset omitted chapter ordering. */
export const sectionUpdateSchema = sectionSchema.partial().extend({
	order: sectionSchema.shape.order.removeDefault().optional(),
});
export const progressSchema = z.object({
	completed: z.boolean().optional(),
	positionSecs: z.number().finite().nonnegative().max(31536000).optional(),
});
export const quizSubmissionSchema = z.object({
	answers: z
		.array(
			z.object({
				questionId: z.string().min(1),
				answer: z.number().int().nonnegative(),
			}),
		)
		.min(1)
		.max(100),
});
export const reviewSchema = z.object({
	rating: z.number().int().min(1).max(5),
	body: z.string().trim().min(1).max(5000),
});

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";
const courseFacts = z.object({
	courseId: z.string(),
	instructorId: z.string(),
	status: z.enum(["draft", "published", "archived"]),
});
/** School permission descriptors. Identity is resolved by the stack, never by request body. */
export const schoolPermissions = definePermissions("school", {
	course: {
		read: permission(
			z.object({
				scope: z.enum(["catalog", "course", "instructor"]),
				courseId: z.string().optional(),
				instructorId: z.string().optional(),
				status: z.string().optional(),
			}),
		),
		create: permission(z.object({ instructorId: z.string() })),
		manage: permission(courseFacts),
	},
	enrollment: {
		read: permission(
			z.object({
				courseId: z.string().optional(),
				instructorId: z.string().optional(),
				userId: z.string().optional(),
				scope: z.enum(["own", "students"]),
			}),
		),
		enroll: permission(courseFacts),
	},
	lesson: {
		read: permission(
			courseFacts.extend({ lessonId: z.string(), isFreePreview: z.boolean() }),
		),
		complete: permission(courseFacts.extend({ lessonId: z.string() })),
	},
	quiz: { submit: permission(courseFacts.extend({ lessonId: z.string() })) },
	certificate: { read: permission(z.object({ certificateId: z.string() })) },
});

"use client";
import { Award } from "lucide-react";
import { useCertificate } from "@btst/stack/plugins/school/client/hooks";
import { SchoolShell } from "./school-shared";

export function CertificatePage({ certificateId }: { certificateId: string }) {
	const { data } = useCertificate(certificateId);
	return (
		<SchoolShell title="Certificate verification">
			<article className="school-certificate">
				<Award size={40} aria-hidden="true" />
				<p>Verified completion</p>
				<h2>{data.courseTitle}</h2>
				<p>All lessons in this course have been completed.</p>
				<dl>
					<div>
						<dt>Completed</dt>
						<dd>
							{new Date(data.completedAt).toLocaleDateString("en-US", {
								timeZone: "UTC",
							})}
						</dd>
					</div>
					<div>
						<dt>Certificate ID</dt>
						<dd>{data.certificateId}</dd>
					</div>
				</dl>
			</article>
		</SchoolShell>
	);
}

"use client";
